import React from 'react';
import { Link } from 'react-router-dom';

function Sidebar() {
  return (
    <aside className="fixed left-0 top-0 h-full w-72 bg-surface-container-lowest z-50 flex flex-col border-r border-glass-stroke backdrop-blur-xl"><div className="p-container-margin flex items-center gap-3 mb-unit"><img alt="Watwise Logo" className="h-8 w-auto object-contain" src="https://lh3.googleusercontent.com/aida/AP1WRLuJKZTRROuMjLpiKEKAXQAVJeuq3uysGxRK4TNcMh7oOK5BgDtNwaZY8dhjvFzpdk-oaQE_Is0fXGV-tmmg07j-hAmVE5kQUmpD2gfTXVNPUjz--F6wNbXHQF8upbBv8Wzdq1A_9WKb5clfPc4p6m4G4lNuMsd0yaa44XMtvDVOhPSVhT6Miv_3oRLhYLKSx5HQIiN5SRwcOr9uDxMAS9e_59XTrDhTdBbd9VBdcN6QzpsQa5-q4O2sswA"/><span className="font-title-md text-title-md text-on-surface">Watwise</span></div><nav className="flex-1 px-card-padding mt-unit space-y-1" data-active-classes="bg-secondary-container text-on-secondary-container shadow-[0_0_15px_rgba(139,92,246,0.3)]"><Link to="/dashboard" className="flex items-center px-4 py-3 rounded-lg transition-all duration-200 group bg-secondary-container text-on-secondary-container shadow-[0_0_15px_rgba(139,92,246,0.3)]"><span className="material-symbols-outlined mr-3 group-hover:text-electric-blue">dashboard</span><span className="font-body-md">Overview</span></Link><Link to="/monitoring" className="flex items-center px-4 py-3 rounded-lg text-on-surface-variant hover:bg-surface-container-highest hover:text-on-surface transition-all duration-200 group"><span className="material-symbols-outlined mr-3 group-hover:text-vibrant-violet">monitoring</span><span className="font-body-md">Real-time Monitoring</span></Link><Link to="/devices" className="flex items-center px-4 py-3 rounded-lg text-on-surface-variant hover:bg-surface-container-highest hover:text-on-surface transition-all duration-200 group"><span className="material-symbols-outlined mr-3 group-hover:text-primary">devices</span><span className="font-body-md">Devices</span></Link><a className="flex items-center px-4 py-3 rounded-lg text-on-surface-variant hover:bg-surface-container-highest hover:text-on-surface transition-all duration-200 group" data-path="usage-analytics" href="#"><span className="material-symbols-outlined mr-3 group-hover:text-tertiary">analytics</span><span className="font-body-md">Usage Analytics</span></a><a className="flex items-center px-4 py-3 rounded-lg text-on-surface-variant hover:bg-surface-container-highest hover:text-on-surface transition-all duration-200 group" data-path="settings" href="#"><span className="material-symbols-outlined mr-3 group-hover:text-outline">settings</span><span className="font-body-md">Settings</span></a></nav><div className="px-card-padding py-card-padding border-t border-glass-stroke"><div className="p-4 rounded-xl bg-surface-container-high/50 backdrop-blur-md flex items-center gap-3"><div className="w-2 h-2 rounded-full bg-electric-blue animate-pulse"></div><span className="text-label-caps font-label-caps text-on-surface-variant uppercase">System: Optimal</span></div></div></aside>
  );
}

export default Sidebar;
